import 'dart:convert';
import 'package:flutter/material.dart';
import 'package:http/http.dart' as http;
import 'package:shared_preferences/shared_preferences.dart';
import 'package:flutter_map/flutter_map.dart';
import 'package:latlong2/latlong.dart';

const apiBase = String.fromEnvironment('API_BASE', defaultValue: 'http://10.0.2.2:8000');

void main() => runApp(const PognaliApp());

class PognaliApp extends StatelessWidget {
  const PognaliApp({super.key});
  @override
  Widget build(BuildContext context) => MaterialApp(
    debugShowCheckedModeBanner: false,
    title: 'Погнали',
    theme: ThemeData(useMaterial3: true, colorSchemeSeed: Colors.orange, scaffoldBackgroundColor: const Color(0xFFF8F7F4)),
    home: const HomeScreen(),
  );
}

class AuthRequired implements Exception {}

class UserModel {
  final int id; final String name, city, bio, photoUrl; final DateTime? birthDate;
  UserModel({required this.id, required this.name, required this.city, this.bio='', this.photoUrl='', this.birthDate});
  factory UserModel.fromJson(Map<String,dynamic> j)=>UserModel(id:j['id'],name:j['name']??'',city:j['city']??'',bio:j['bio']??'',photoUrl:j['photo_url']??'',birthDate:j['birth_date']==null?null:DateTime.tryParse(j['birth_date']));
  int? get age { if(birthDate==null)return null; final n=DateTime.now(); var a=n.year-birthDate!.year; if(DateTime(n.year,birthDate!.month,birthDate!.day).isAfter(n))a--; return a; }
}

class EventModel {
  final int id, people, capacity; final String title, place, time, description; final double lat,lon; final bool joined;
  final DateTime startsAt;
  EventModel({required this.id,required this.title,required this.place,required this.time,required this.people,required this.capacity,required this.startsAt,this.description='',this.lat=44.9521,this.lon=34.1024,this.joined=false});
  factory EventModel.fromJson(Map<String,dynamic> j){final d=DateTime.tryParse(j['starts_at'].toString())?.toLocal()??DateTime.now(); return EventModel(id:j['id'],title:j['title'],place:j['location'],time:'${d.day.toString().padLeft(2,'0')}.${d.month.toString().padLeft(2,'0')}  ${d.hour.toString().padLeft(2,'0')}:${d.minute.toString().padLeft(2,'0')}',startsAt:d,people:j['participants']??0,capacity:j['capacity']??10,description:j['description']??'',lat:(j['lat']??44.9521).toDouble(),lon:(j['lon']??34.1024).toDouble(),joined:j['is_joined']??false);}
}

class Api {
  static Future<String?> token() async => (await SharedPreferences.getInstance()).getString('token');
  static Future<void> saveToken(String t) async => (await SharedPreferences.getInstance()).setString('token',t);
  static Future<void> logout() async => (await SharedPreferences.getInstance()).remove('token');
  static Future<UserModel> devLogin({required String id, required String name}) async { final r=await http.post(Uri.parse('$apiBase/auth/dev'),headers:{'Content-Type':'application/json'},body:jsonEncode({'provider_user_id':id,'name':name})); if(r.statusCode!=200)throw Exception('Не удалось войти'); final j=jsonDecode(r.body); await saveToken(j['access_token']); return UserModel.fromJson(j['user']); }
  static Future<List<EventModel>> events() async { final t=await token(); final r=await http.get(Uri.parse('$apiBase/events'),headers:{if(t!=null)'Authorization':'Bearer $t'}); if(r.statusCode!=200)throw Exception('Не удалось загрузить события'); return (jsonDecode(r.body) as List).map((x)=>EventModel.fromJson(x)).toList(); }
  static Future<EventModel> event(int id) async { final t=await token(); final r=await http.get(Uri.parse('$apiBase/events/$id'),headers:{if(t!=null)'Authorization':'Bearer $t'}); if(r.statusCode!=200)throw Exception('Событие не найдено'); return EventModel.fromJson(jsonDecode(r.body)); }
  static Future<List<UserModel>> participants(int id) async { final r=await http.get(Uri.parse('$apiBase/events/$id/participants')); if(r.statusCode!=200)throw Exception('Не удалось загрузить участников'); return (jsonDecode(r.body) as List).map((x)=>UserModel.fromJson(x)).toList(); }
  static Future<List<dynamic>> messages(int id) async { final t=await token(); if(t==null)throw AuthRequired(); final r=await http.get(Uri.parse('$apiBase/events/$id/messages'),headers:{'Authorization':'Bearer $t'}); if(r.statusCode==401)throw AuthRequired(); if(r.statusCode!=200)throw Exception('Не удалось загрузить чат'); return jsonDecode(r.body) as List; }
  static Future<void> sendMessage(int id,String text) async { final t=await token(); if(t==null)throw AuthRequired(); final r=await http.post(Uri.parse('$apiBase/events/$id/messages'),headers:{'Authorization':'Bearer $t','Content-Type':'application/json'},body:jsonEncode({'text':text})); if(r.statusCode==401)throw AuthRequired(); if(r.statusCode!=200)throw Exception('Не удалось отправить сообщение'); }
  static Future<void> join(int id) async { final t=await token(); if(t==null)throw AuthRequired(); final r=await http.post(Uri.parse('$apiBase/events/$id/join'),headers:{'Authorization':'Bearer $t'}); if(r.statusCode==401)throw AuthRequired(); if(r.statusCode!=200)throw Exception((jsonDecode(r.body)['detail']??'Не удалось присоединиться').toString()); }
  static Future<void> leave(int id) async { final t=await token(); if(t==null)throw AuthRequired(); final r=await http.post(Uri.parse('$apiBase/events/$id/leave'),headers:{'Authorization':'Bearer $t'}); if(r.statusCode==401)throw AuthRequired(); if(r.statusCode!=200)throw Exception('Не удалось выйти'); }
  static Future<UserModel> me() async { final t=await token(); if(t==null)throw AuthRequired(); final r=await http.get(Uri.parse('$apiBase/me'),headers:{'Authorization':'Bearer $t'}); if(r.statusCode==401)throw AuthRequired(); return UserModel.fromJson(jsonDecode(r.body)); }
  static Future<UserModel> updateMe({String? name,String? city,DateTime? birthDate,String? bio,String? photoUrl}) async { final t=await token(); if(t==null)throw AuthRequired(); final b=<String,dynamic>{}; if(name!=null)b['name']=name;if(city!=null)b['city']=city;if(birthDate!=null)b['birth_date']=birthDate.toIso8601String().substring(0,10);if(bio!=null)b['bio']=bio;if(photoUrl!=null)b['photo_url']=photoUrl; final r=await http.patch(Uri.parse('$apiBase/me'),headers:{'Authorization':'Bearer $t','Content-Type':'application/json'},body:jsonEncode(b));if(r.statusCode==401)throw AuthRequired();return UserModel.fromJson(jsonDecode(r.body)); }
  static Future<void> createEvent({required String title,required String location,required DateTime startsAt,required int capacity,String description=''}) async { final t=await token();if(t==null)throw AuthRequired();final r=await http.post(Uri.parse('$apiBase/events'),headers:{'Authorization':'Bearer $t','Content-Type':'application/json'},body:jsonEncode({'title':title,'city':'Симферополь','location':location,'starts_at':startsAt.toUtc().toIso8601String(),'capacity':capacity,'description':description,'lat':44.9521,'lon':34.1024}));if(r.statusCode==401)throw AuthRequired();if(r.statusCode!=200)throw Exception((jsonDecode(r.body)['detail']??'Не удалось создать событие').toString()); }
}

class HomeScreen extends StatefulWidget{const HomeScreen({super.key});@override State<HomeScreen> createState()=>_HomeScreenState();}
class _HomeScreenState extends State<HomeScreen>{
  int tab=0; bool mapMode=true,loading=true; String filter='Сегодня'; List<EventModel> all=[];
