setState(()=>tab=0);},destinations:const[NavigationDestination(icon:Icon(Icons.map),label:'Карта'),NavigationDestination(icon:Icon(Icons.add_circle_outline),label:'Создать'),NavigationDestination(icon:Icon(Icons.person_outline),label:'Профиль')]));
  Widget _map(List<EventModel> es)=>FlutterMap(options:const MapOptions(initialCenter:LatLng(44.9521,34.1024),initialZoom:13),children:[TileLayer(urlTemplate:'https://tile.openstreetmap.org/{z}/{x}/{y}.png',userAgentPackageName:'ru.pognali.app'),MarkerLayer(markers:[for(final e in es)Marker(point:LatLng(e.lat,e.lon),width:62,height:62,child:GestureDetector(onTap:()=>_open(e),child:Container(decoration:BoxDecoration(color:Theme.of(context).colorScheme.primary,shape:BoxShape.circle,border:Border.all(color:Colors.white,width:3)),child:Center(child:Text('${e.people}/${e.capacity}',style:const TextStyle(color:Colors.white,fontWeight:FontWeight.bold))))))])]);
  Widget _list(List<EventModel> es)=>ListView.builder(padding:const EdgeInsets.all(12),itemCount:es.length,itemBuilder:(_,i)=>_card(es[i]));
  Widget _card(EventModel e)=>Card(child:InkWell(onTap:()=>_open(e),borderRadius:BorderRadius.circular(14),child:Padding(padding:const EdgeInsets.all(16),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(e.title,style:Theme.of(context).textTheme.titleLarge?.copyWith(fontWeight:FontWeight.w700)),const SizedBox(height:8),Text('🕒 ${e.time}'),Text('📍 ${e.place}'),Text('👥 ${e.people}/${e.capacity}'),const SizedBox(height:12),SizedBox(width:double.infinity,child:FilledButton(onPressed:e.people>=e.capacity&&!e.joined?null:()=>_open(e),child:Text(e.joined?'Я ИДУ':e.people>=e.capacity?'МЕСТ НЕТ':'ПОЙДУ')))]))));
