class EventSheet extends StatefulWidget{final EventModel event;final VoidCallback onChanged;const EventSheet({super.key,required this.event,required this.onChanged});@override State<EventSheet> createState()=>_EventSheetState();}
class _EventSheetState extends State<EventSheet>{late EventModel e;List<UserModel> users=[];List<dynamic> messages=[];final msg=TextEditingController();bool busy=false;@override void initState(){super.initState();e=widget.event;_load();}Future<void> _load()async{try{final u=await Api.participants(e.id);if(mounted)setState(()=>users=u);}catch(_){}if(e.joined){try{final m=await Api.messages(e.id);if(mounted)setState(()=>messages=m);}catch(_) {}}}Future<void> _join()async{try{setState(()=>busy=true);await Api.join(e.id);final x=await Api.event(e.id);if(mounted)setState(()=>e=x);await _load();}catch(x){if(x is AuthRequired){Navigator.pop(context);widget.onChanged();return;}if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(x.toString())));}finally{if(mounted)setState(()=>busy=false);}}Future<void> _leave()async{try{setState(()=>busy=true);await Api.leave(e.id);final x=await Api.event(e.id);if(mounted)setState(()=>e=x);messages=[];}catch(x){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(x.toString())));}finally{if(mounted)setState(()=>busy=false);}}Future<void> _send()async{final text=msg.text.trim();if(text.isEmpty)return;try{await Api.sendMessage(e.id,text);msg.clear();final m=await Api.messages(e.id);if(mounted)setState(()=>messages=m);}catch(x){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(x.toString())));}}@override Widget build(BuildContext c)=>Padding(padding:EdgeInsets.fromLTRB(20,4,20,20+MediaQuery.of(c).viewInsets.bottom),child:SingleChildScrollView(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(e.title,style:Theme.of(c).textTheme.headlineSmall?.copyWith(fontWeight:FontWeight.bold)),const SizedBox(height:10),Text('🕒 ${e.time}'),Text('📍 ${e.place}'),Text('👥 ${e.people}/${e.capacity}'),if(e.description.isNotEmpty)...[const SizedBox(height:12),Text(e.description)],const SizedBox(height:16),Text('Участники',style:Theme.of(c).textTheme.titleMedium?.copyWith(fontWeight:FontWeight.bold)),const SizedBox(height:8),Wrap(spacing:8,runSpacing:8,children:[for(final u in users)Chip(avatar:u.photoUrl.isEmpty?const Icon(Icons.person,size:18):CircleAvatar(backgroundImage:NetworkImage(u.photoUrl)),label:Text(u.name))]),const SizedBox(height:16),if(e.joined)...[Row(children:[Expanded(child:OutlinedButton(onPressed:busy?null:_leave,child:const Text('ВЫЙТИ'))),const SizedBox(width:8),Expanded(child:FilledButton(onPressed:()=>_chat(context),child:const Text('ЧАТ')))] )]else SizedBox(width:double.infinity,child:FilledButton(onPressed:(e.people>=e.capacity||busy)?null:_join,child:Text(e.people>=e.capacity?'МЕСТ НЕТ':'ПОЙДУ')))])));
  Future<void> _chat(BuildContext c)async{await showModalBottomSheet(context:c,isScrollControlled:true,showDragHandle:true,builder:(_)=>Padding(padding:EdgeInsets.fromLTRB(16,8,16,16+MediaQuery.of(c).viewInsets.bottom),child:SizedBox(height:MediaQuery.of(c).size.height*0.72,child:Column(children:[Row(children:[Text('Чат события',style:Theme.of(c).textTheme.titleLarge?.copyWith(fontWeight:FontWeight.bold)),const Spacer(),IconButton(onPressed:()=>Navigator.pop(c),icon:const Icon(Icons.close))]),Expanded(child:ListView(children:[for(final m in messages)ListTile(title:Text(m['text']??''),subtitle:Text(m['user_name']??''))])),Row(children:[Expanded(child:TextField(controller:msg,onSubmitted:(_)=>_send(),decoration:const InputDecoration(hintText:'Напиши сообщение'))),IconButton(onPressed:_send,icon:const Icon(Icons.send))])]))));}
}

class ProfileScreen extends StatefulWidget{const ProfileScreen({super.key});@override State<ProfileScreen> createState()=>_ProfileScreenState();}
class _ProfileScreenState extends State<ProfileScreen>{UserModel? user;bool loading=true;@override void initState(){super.initState();_load();}Future<void> _load()async{try{final u=await Api.me();if(mounted)setState(()=>user=u);}catch(_){}finally{if(mounted)setState(()=>loading=false);}}@override Widget build(BuildContext c){if(loading)return const Scaffold(body:Center(child:CircularProgressIndicator()));if(user==null)return Scaffold(appBar:AppBar(title:const Text('Профиль')),body:Center(child:FilledButton(onPressed:()=>_auth(c),child:const Text('Войти'))));final u=user!;return Scaffold(appBar:AppBar(title:const Text('Профиль'),actions:[IconButton(onPressed:()async{await Api.logout();if(mounted)setState(()=>user=null);},icon:const Icon(Icons.logout))]),body:ListView(padding:const EdgeInsets.all(20),children:[Center(child:CircleAvatar(radius:44,backgroundImage:u.photoUrl.isNotEmpty?NetworkImage(u.photoUrl):null,child:u.photoUrl.isEmpty?const Icon(Icons.person,size:44):null)),const SizedBox(height:12),Center(child:Text(u.name,style:Theme.of(c).textTheme.headlineSmall?.copyWith(fontWeight:FontWeight.bold))),Center(child:Text([if(u.age!=null)'${u.age} лет',if(u.city.isNotEmpty)u.city].join(' · '))),if(u.bio.isNotEmpty)...[const SizedBox(height:14),Text(u.bio,textAlign:TextAlign.center)],const SizedBox(height:24),FilledButton.icon(onPressed:()=>_editProfile(c),icon:const Icon(Icons.edit),label:const Text('Редактировать профиль')),const SizedBox(height:20),const Text('Создавай события, иди на них и встречай людей. Здесь нет ленты и лайков — только реальные планы.')]);}Future<void> _editProfile(BuildContext c) async {
  final u=user!;
  final name=TextEditingController(text:u.name);
  final city=TextEditingController(text:u.city);
  final bio=TextEditingController(text:u.bio);
  await showModalBottomSheet(context:c,isScrollControlled:true,showDragHandle:true,builder:(sheet)=>Padding(padding:EdgeInsets.fromLTRB(20,8,20,20+MediaQuery.of(c).viewInsets.bottom),child:SingleChildScrollView(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[
    Text('Редактировать профиль',style:Theme.of(c).textTheme.headlineSmall?.copyWith(fontWeight:FontWeight.bold)),
    const SizedBox(height:16),
    TextField(controller:name,decoration:const InputDecoration(labelText:'Имя')),
    TextField(controller:city,decoration:const InputDecoration(labelText:'Город')),
    TextField(controller:bio,maxLines:3,decoration:const InputDecoration(labelText:'О себе (необязательно)')),
    const SizedBox(height:18),
    SizedBox(width:double.infinity,child:FilledButton(onPressed:()async{try{final updated=await Api.updateMe(name:name.text.trim(),city:city.text.trim(),bio:bio.text.trim());if(mounted)setState(()=>user=updated);if(sheet.mounted)Navigator.pop(sheet);}catch(e){if(sheet.mounted)ScaffoldMessenger.of(sheet).showSnackBar(SnackBar(content:Text(e.toString())));}},child:const Text('СОХРАНИТЬ'))),
  ]))));
}
